  "odds.py": "import math


def american_probability(value):
    if isinstance(value, bool):
        raise ValueError("bool is not an accepted type")
    if value is None:
        raise ValueError("None is not an accepted type")
    if isinstance(value, (int, float)):
        v = float(value)
    elif isinstance(value, str):
        s = value.strip()
        if not s:
            raise ValueError("empty or whitespace-only string is not numeric")
        try:
            v = float(s)
        except (ValueError, OverflowError):
            raise ValueError(f"nonnumeric string: {value!r}")
    else:
        raise ValueError(f"unsupported type: {type(value).__name__}")
    if not math.isfinite(v):
        raise ValueError("value must be finite")
    if abs(v) < 100:
        raise ValueError("absolute value must be >= 100")
    if v > 0:
        return 100.0 / (v + 100.0)
    else:
        return -v / (-v + 100.0)
